INSERT OR IGNORE INTO app_settings (setting_key, value_json, description) VALUES
  ('about_sadaqah', '{"sadaqahTitleEn":"A continuing Sadaqah Jariyah","sadaqahTitleAr":"صدقة جارية مستمرة","sadaqahBodyEn":"Hassoun is built as a continuing charity dedicated to spreading beneficial Islamic knowledge, helping people protect their prayers, read Qur’an, learn and teach their families.","sadaqahBodyAr":"بُني Hassoun كصدقة جارية لنشر العلم الإسلامي النافع ومساعدة الناس على المحافظة على الصلاة وقراءة القرآن والتعلم وتعليم أسرهم.","names":["Abdul Jalil Hassoun","Salwa Hassoun"],"donationEnabled":false,"donationUrl":"","donationTitleEn":"Contribute to this Sadaqah Jariyah","donationTitleAr":"ساهم في هذه الصدقة الجارية","donationBodyEn":"Your contribution can help support hosting, development, Qur’an tools, prayer services and future educational features so the benefit can continue for more people.","donationBodyAr":"يمكن لمساهمتك أن تساعد في دعم الاستضافة والتطوير وأدوات القرآن وخدمات الصلاة والميزات التعليمية القادمة ليستمر النفع لعدد أكبر من الناس."}', 'About page memorial dedication and verified donation configuration.'),
  ('feature_guide', '{"enabled":true,"titleEn":"Learn the App","titleAr":"تعرّف على التطبيق","introEn":"Search any Hassoun feature and learn how it works with easy steps, examples and tips.","introAr":"ابحث عن أي ميزة في Hassoun وتعلم طريقة استخدامها بخطوات وأمثلة ونصائح سهلة."}', 'Feature guide visibility and introductory content.');
